from rcb_client import Robot
from PIL import Image
import numpy as np
r=Robot(timeout=30); o=r.get_obs(depth=True,video='none')
for c,im in o.last.items(): Image.fromarray(im).save('/app/output/recheck_'+c+'.jpg')
for c,d in o.last_depth.items(): np.save('/app/output/recheck_depth_'+c+'.npy',d)
cam='egocentric_mirrored_camera'; E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);R=E[:,:3];t=E[:,3];K=np.array(o.meta['cameras'][cam]['intrinsic_cv'])
def p(u,v):
 d=o.last_depth[cam][int(v),int(u)];xyz=np.linalg.inv(K)@np.array([u,v,1])*d;return float(d),(R.T@(xyz-t)).tolist()
for n,uv in {'red_center':(515,138),'red_mouth':(512,138),'red_table_near':(540,170),'blue_mug':(600,205),'white_side':(360,205),'white_up':(585,100),'red_table':(515,190)}.items():print(n,uv,p(*uv))
print('now',o.meta['proprio']['now'][8:16], 'timeleft',o.meta['time_left_s'])
PY

